"""Hardware-only AV1 through the pinned private pixelflux 2.2.3 runtime."""
from collections import deque
import os
import stat
import struct
import threading
import time

from .hevc_capture import PrivateLiveControls, runtime

FIRST_FRAME_TIMEOUT = 8
MAX_PENDING_FRAMES = 120
MAX_PACKET_BYTES = 16 * 1024 * 1024
MAX_PENDING_BYTES = 32 * 1024 * 1024
MAX_DIMENSION = 8192
MAX_OBUS = 4096


class Av1Error(RuntimeError):
    """A stable diagnostic code plus a human-readable failure detail."""
    def __init__(self, code, message):
        self.code = code
        super().__init__(message)


def _error(exc, code, prefix):
    return Av1Error(getattr(exc, "code", code), prefix + str(exc))


def _probe_device(path):
    result = {"path": path, "read_write": False, "euid": os.geteuid(),
              "egid": os.getegid(), "groups": os.getgroups()}
    try:
        info = os.stat(path)
        result.update(uid=info.st_uid, gid=info.st_gid, mode=oct(stat.S_IMODE(info.st_mode)))
        if not stat.S_ISCHR(info.st_mode):
            return result, "device_not_character", "Selected render node is not a character device"
        descriptor = os.open(path, os.O_RDWR | os.O_CLOEXEC | os.O_NONBLOCK)
        os.close(descriptor)
        result["read_write"] = True
        return result, None, None
    except FileNotFoundError:
        return result, "device_missing", "Selected render node does not exist"
    except PermissionError as exc:
        return result, "device_permission_denied", "Cannot open selected render node: " + str(exc)
    except OSError as exc:
        return result, "device_open_failed", "Render node access check failed: " + str(exc)


def probe_capability(node, use_cpu=False, wayland=False):
    """Inspect the selected node as the current user, without starting capture.

    The result is a capability snapshot, not proof that a real encode succeeded.
    Node indices are zero-based: index 0 names /dev/dri/renderD128.
    """
    valid_node = isinstance(node, int) and not isinstance(node, bool) and node >= 0
    path = "/dev/dri/renderD" + str(128 + node) if valid_node else None
    result = {"available": False, "reason_code": None, "reason": None,
              "node_index": node if valid_node else None, "node_path": path,
              "device": None, "hardware_encoders": {}, "hardware_formats": {},
              "use_cpu": bool(use_cpu), "wayland": bool(wayland),
              "probe_kind": "capability", "hardware_verified": False}

    def refused(code, reason):
        result.update(reason_code=code, reason=reason)
        return result

    if use_cpu:
        return refused("cpu_mode", "AV1 requires GPU encoding; CPU mode is enabled or locked")
    if wayland:
        return refused("wayland_unsupported", "AV1 currently requires X11 capture")
    if not valid_node:
        return refused("invalid_render_node", "Selected GPU has no valid render-node index")
    result["device"], code, reason = _probe_device(path)
    if code:
        return refused(code, reason)
    try:
        module = runtime()
        if not all(callable(getattr(module, name, None)) for name in (
                "ScreenCapture", "CaptureSettings", "hardware_encoders", "hardware_formats")):
            return refused("runtime_unavailable", "Private AV1 runtime lacks a required API")
    except Exception as exc:
        return refused("runtime_unavailable", "Private AV1 runtime unavailable: " + str(exc))
    try:
        result["hardware_encoders"] = {str(key): str(value) for key, value in module.hardware_encoders(node).items()}
        result["hardware_formats"] = {str(key): [str(item) for item in value]
                                      for key, value in module.hardware_formats(node).items()}
    except Exception as exc:
        return refused("capability_probe_failed", "AV1 capability probe failed: " + str(exc))
    if "av1" not in result["hardware_encoders"]:
        return refused("av1_encoder_missing", "Selected GPU has no AV1 encoder; using H.264")
    if "420-8" not in result["hardware_formats"].get("av1", ()):
        return refused("av1_format_unsupported", "Selected GPU has no AV1 8-bit 4:2:0 encoder")
    result.update(available=True, reason_code="available", reason="AV1 8-bit 4:2:0 capability available")
    return result


def _keyframe_has_sequence(payload):
    """Require a bounded Sequence Header OBU before the first frame OBU.

    pixelflux 2.2.3 submits its sequence parameters on every forced key frame.
    Verify the driver output instead of grafting an earlier sequence onto it.
    """
    position = 0
    count = 0
    have_sequence = False
    while position < len(payload):
        count += 1
        if count > MAX_OBUS:
            raise Av1Error("obu_invalid", "AV1 temporal unit has too many OBUs")
        header = payload[position]
        position += 1
        if header & 0x81 or not header & 2:
            raise Av1Error("obu_invalid", "Invalid AV1 low-overhead OBU header")
        kind = (header >> 3) & 15
        if header & 4:
            if position >= len(payload) or payload[position] & 7:
                raise Av1Error("obu_invalid", "Invalid AV1 OBU extension")
            position += 1
        size = 0
        for index in range(8):
            if position >= len(payload):
                raise Av1Error("obu_invalid", "Truncated AV1 OBU size")
            value = payload[position]
            position += 1
            size |= (value & 127) << (7 * index)
            if size > MAX_PACKET_BYTES:
                raise Av1Error("obu_invalid", "AV1 OBU exceeds the packet limit")
            if not value & 128:
                break
        else:
            raise Av1Error("obu_invalid", "AV1 OBU size exceeds eight bytes")
        if size > len(payload) - position:
            raise Av1Error("obu_invalid", "Truncated AV1 OBU payload")
        if kind == 1:
            if not size or size > 4096:
                raise Av1Error("obu_invalid", "Invalid AV1 sequence header size")
            have_sequence = True
        elif kind in (3, 6):
            if not size:
                raise Av1Error("obu_invalid", "Empty AV1 frame header")
            return have_sequence
        position += size
    return False


class CaptureStatistics:
    """Constant-space session counters and a bounded one-second rate window."""
    def __init__(self, now):
        self.started_at = now
        self.stopped_at = None
        self.frames = 0
        self.payload_bytes = 0
        self.wire_bytes = 0
        self.keyframes = 0
        self.keyframe_requests = 0
        self.first_keyframe_ms = None
        self.last_key_at = None
        self.last_key_frame = None
        self.last_key_interval_ms = None
        self.max_key_interval_ms = None
        self.last_key_interval_frames = None
        self.max_key_interval_frames = None
        self.window = deque()
        self.window_bytes = 0
        self.peak_bitrate = 0

    def _prune(self, now):
        while self.window and (self.window[0][0] <= now - 1 or len(self.window) > 4096):
            self.window_bytes -= self.window.popleft()[1]

    def record(self, data, now):
        payload_size = len(data) - 10
        self.frames += 1
        self.payload_bytes += payload_size
        self.wire_bytes += len(data)
        if data[1]:
            self.keyframes += 1
            if self.first_keyframe_ms is None:
                self.first_keyframe_ms = max(0, now - self.started_at) * 1000
            if self.last_key_at is not None:
                self.last_key_interval_ms = max(0, now - self.last_key_at) * 1000
                self.max_key_interval_ms = max(self.max_key_interval_ms or 0, self.last_key_interval_ms)
                self.last_key_interval_frames = self.frames - self.last_key_frame
                self.max_key_interval_frames = max(self.max_key_interval_frames or 0, self.last_key_interval_frames)
            self.last_key_at = now
            self.last_key_frame = self.frames
        self.window.append((now, payload_size))
        self.window_bytes += payload_size
        self._prune(now)
        self.peak_bitrate = max(self.peak_bitrate, self.window_bytes * 8)

    def snapshot(self, now):
        self._prune(now)
        elapsed = max(0, (self.stopped_at if self.stopped_at is not None else now) - self.started_at)
        return {"elapsed_seconds": round(elapsed, 3), "frames_encoded": self.frames,
                "payload_bytes": self.payload_bytes, "wire_bytes": self.wire_bytes,
                "keyframes": self.keyframes, "keyframe_requests": self.keyframe_requests,
                "first_keyframe_ms": self.first_keyframe_ms,
                "fps": len(self.window), "bitrate_bps": self.window_bytes * 8,
                "average_fps": self.frames / elapsed if elapsed else 0,
                "average_bitrate_bps": self.payload_bytes * 8 / elapsed if elapsed else 0,
                "peak_bitrate_bps": self.peak_bitrate, "rate_window_seconds": 1,
                "keyframe_interval_ms": self.last_key_interval_ms,
                "max_keyframe_interval_ms": self.max_key_interval_ms,
                "keyframe_interval_frames": self.last_key_interval_frames,
                "max_keyframe_interval_frames": self.max_key_interval_frames}


def available():
    """Whether the private runtime exposes the required API, not GPU support."""
    try:
        module = runtime()
        return all(callable(getattr(module, name, None)) for name in (
            "ScreenCapture", "CaptureSettings", "hardware_encoders", "hardware_formats"))
    except (ImportError, OSError, RuntimeError):
        return False


def packet(native, width, height):
    """Convert the native 12-byte video header to the existing geometry/ACK wire.

    Source dimensions stay authoritative: an encoder may pad its coded picture,
    but that must not resize the desktop or its input coordinate space.
    """
    if len(native) <= 12:
        raise Av1Error("native_packet_invalid", "AV1 encoder returned a truncated frame")
    if len(native) > MAX_PACKET_BYTES:
        raise Av1Error("native_packet_too_large", "AV1 encoder returned an oversized frame")
    tag, kind, frame_id, y, coded_w, coded_h, _reference = struct.unpack("!BBHHHHH", native[:12])
    frame_kind = kind & 7  # The native anchor flag (0x08) is not a key frame.
    if tag != 4 or kind >> 4 != 4 or frame_kind not in (0, 1, 2):
        raise Av1Error("native_packet_invalid", "AV1 encoder returned an unexpected codec or frame type")
    if (y != 0 or not 0 < width <= MAX_DIMENSION or not 0 < height <= MAX_DIMENSION
            or not width <= coded_w < width + 128
            or not height <= coded_h < height + 128):
        raise Av1Error("native_geometry_invalid", "AV1 encoder returned incompatible frame geometry")
    header = struct.pack("!BBHHHH", 6, int(frame_kind == 1), frame_id, 0, width, height)
    return header + native[12:], frame_id


class Av1Capture(PrivateLiveControls):
    def __init__(self):
        try:
            self.capture = runtime().ScreenCapture()
        except Exception as exc:
            raise _error(exc, "runtime_unavailable", "AV1 runtime initialization failed: ") from exc
        self._lock = threading.Lock()
        self._error = None
        self._stopped = False
        self._state = "idle"
        self._stats = None
        self.capability = None

    def _validate_info(self, info):
        if not info:
            raise Av1Error("runtime_info_unavailable", "AV1 runtime returned no stream information")
        reason = str(info.get("encoder_reason") or "unexpected codec, hardware or pixel format")
        if str(info.get("codec")).lower() != "av1":
            raise Av1Error("runtime_codec_changed", "AV1 runtime changed codec: " + reason)
        if info.get("hardware") is not True:
            code = "runtime_software_fallback" if self._state == "running" else "initial_hardware_mismatch"
            raise Av1Error(code, "AV1 hardware encoding unavailable: " + reason)
        if info.get("bit_depth") != 8 or info.get("fullcolor") is not False or info.get("striped") is not False:
            raise Av1Error("runtime_format_changed", "AV1 runtime changed pixel format: " + reason)
        return info

    def check_health(self):
        """Also called by the server after startup to catch runtime demotion."""
        with self._lock:
            if self._error is not None:
                raise self._error
            if self._stopped:
                raise Av1Error("capture_stopped", "AV1 capture stopped")
        try:
            return self._validate_info(self.capture.stream_info())
        except Exception as exc:
            with self._lock:
                self._error = _error(exc, "runtime_health_failed", "AV1 hardware health check failed: ")
                self._state = "failed"
            raise self._error from exc

    def start_capture(self, legacy, callback):
        self._state = "starting"
        self._stats = CaptureStatistics(time.monotonic())
        try:
            self._start_capture(legacy, callback)
        except Exception as exc:
            with self._lock:
                self._error = exc if isinstance(exc, Av1Error) else _error(
                    exc, "encoder_init_failed", "AV1 capture start failed: ")
                self._state = "failed"
                self._stats.stopped_at = time.monotonic()
            if self._error is exc:
                raise
            raise self._error from exc

    def _start_capture(self, legacy, callback):
        module = runtime()
        if (legacy.scale != 1 or legacy.auto_adjust_screen_capture_size
                or not 0 < legacy.capture_width <= MAX_DIMENSION
                or not 0 < legacy.capture_height <= MAX_DIMENSION):
            raise Av1Error("geometry_unsupported", "AV1 requires fixed full-frame capture geometry")
        node = legacy.vaapi_render_node_index
        self.capability = probe_capability(node, use_cpu=legacy.use_cpu)
        if not self.capability["available"]:
            raise Av1Error(self.capability["reason_code"], self.capability["reason"])

        settings = module.CaptureSettings()
        for name in ("capture_width", "capture_height", "capture_x", "capture_y", "capture_cursor",
                     "target_fps", "scale", "auto_adjust_screen_capture_size",
                     "use_paint_over_quality", "paint_over_trigger_frames", "damage_block_threshold",
                     "damage_block_duration", "watermark_location_enum"):
            setattr(settings, name, getattr(legacy, name))
        watermark = legacy.watermark_path
        settings.watermark_path = watermark.decode("utf-8") if isinstance(watermark, bytes) else watermark
        for name in ("crf", "paintover_crf", "paintover_burst_frames", "streaming_mode"):
            setattr(settings, "video_" + name, getattr(legacy, "h264_" + name))
        settings.codec = "av1"
        settings.use_cpu = False
        settings.use_wayland = False
        settings.video_fullframe = True
        settings.video_fullcolor = False
        settings.video_bit_depth = 8
        # StripeFrame has no keyframe attribute. Keep the upstream header for
        # its codec and frame-kind fields, then adapt it to our existing wire.
        settings.omit_stripe_headers = False
        settings.encode_node_index = node
        accepted = False
        have_keyframe = False
        pending = []
        pending_bytes = 0
        first_frame = threading.Event()

        def deliver(frame):
            nonlocal have_keyframe, pending_bytes
            # Native callback exceptions may be swallowed by the capture
            # thread. Retain them for startup and the server's health monitor.
            with self._lock:
                if self._stopped or self._error is not None:
                    return
                try:
                    data, frame_id = packet(bytes(frame), settings.capture_width, settings.capture_height)
                    if data[1] and not _keyframe_has_sequence(memoryview(data)[10:]):
                        raise Av1Error("sequence_header_missing", "AV1 key frame has no preceding sequence header")
                    if not have_keyframe:
                        if not data[1]:
                            return
                        have_keyframe = True
                    self._stats.record(data, time.monotonic())
                    if accepted:
                        callback(data, frame_id)
                    elif (len(pending) < MAX_PENDING_FRAMES
                          and pending_bytes + len(data) <= MAX_PENDING_BYTES):
                        pending.append((data, frame_id))
                        pending_bytes += len(data)
                    else:
                        raise Av1Error("startup_queue_overflow", "AV1 startup frame queue overflow")
                except Exception as exc:
                    self._error = _error(exc, "frame_delivery_failed", "AV1 frame delivery failed: ")
                    self._state = "failed"
                first_frame.set()

        try:
            self.capture.start_capture(deliver, settings)
            self._settings = settings
            if not first_frame.wait(FIRST_FRAME_TIMEOUT):
                raise Av1Error("first_keyframe_timeout", "AV1 encoder produced no key frame within 8 seconds")
            self.check_health()
            with self._lock:
                if self._error is not None:
                    raise self._error
                for data, frame_id in pending:
                    callback(data, frame_id)
                pending.clear()
                pending_bytes = 0
                accepted = True
                self._state = "running"
            self.request_idr_frame()
        except Exception as exc:
            with self._lock:
                self._error = _error(exc, "encoder_init_failed", "AV1 encoder initialization failed: ")
                self._state = "failed"
            # A secondary stop error must not erase the original failure code.
            try:
                self.stop_capture()
            except Exception as stop_error:
                self._error.stop_error = str(stop_error)
            raise self._error from exc

    def stop_capture(self):
        with self._lock:
            self._stopped = True
            if self._stats and self._stats.stopped_at is None:
                self._stats.stopped_at = time.monotonic()
            if self._error is None:
                self._state = "stopped"
        try:
            self.capture.stop_capture()
        except Exception as exc:
            raise _error(exc, "native_stop_failed", "AV1 native capture stop failed: ") from exc

    def request_idr_frame(self):
        try:
            self.capture.request_idr_frame()
            with self._lock:
                if self._stats:
                    self._stats.keyframe_requests += 1
        except Exception as exc:
            raise _error(exc, "keyframe_request_failed", "AV1 key-frame request failed: ") from exc

    def statistics(self):
        with self._lock:
            result = self._stats.snapshot(time.monotonic()) if self._stats else {}
            result.update(state=self._state, reason_code=getattr(self._error, "code", None))
            return result
